int http_find_header(const struct htx *htx, const struct ist name, struct http_hdr_ctx *ctx, int full) /* <=== http_find_header */ 
{
	return __http_find_header(htx, &name, ctx, HTTP_FIND_FL_MATCH_STR | (full ? HTTP_FIND_FL_FULL : 0));
}

static inline int chunk_memcat(struct buffer *chk, const char *src, /* <=== chunk_memcat */ 
			       size_t len)
{
	if (unlikely(chk->data + len > chk->size))
		return 0;

	memcpy(chk->area + chk->data, src, len);
	chk->data += len;
	return 1;
}

